// truchet 背景板


vec2 cent6(vec2 p) //1356 15 22 1147 596
{
        vec2 k = vec2(sqrt(3.), 1);
        // vec4 
        vec2 a = (round(p / k - .0) + .0) * k;
        vec2 b = (round(p / k - .5) + .5) * k;
        vec2 c = a;
        if (length(p - a) > length(p - b)) c = b;
        return c;
}

void mainImage(out vec4 O, vec2 u) {
        O = vec4(.5);
        vec2 R = iResolution.xy;
        u = 3. * (u + u - R) / R.y;
        vec2 f = abs(u - cent6(u));

        //vec2 e = vec2(sqrt(3.)/6., .5);
        vec2 n = normalize(vec2(-.5, sqrt(3.) / 6.));

        if (dot(f, n) < 0.) f = reflect(f, n);

        f = abs(f);

        f -= abs(n.yx) / (1. + sqrt(3.));

        if(f.y<0.)f.x=9.;// fix
        f = abs(f);
        // exp(-80.*
        O += smoothstep(.015, .0, abs(.03 - min(f.x, f.y)));

}
